    /* Native Streamlit 1.64 theme semantics. */
    --scapp-v2-bg: var(--st-background-color);
    --scapp-v2-bg-secondary: var(--st-secondary-background-color);
    --scapp-v2-text: var(--st-text-color);
    --scapp-v2-muted-text: color-mix(in srgb, var(--st-text-color) 70%, transparent);
    --scapp-v2-border: var(--st-border-color);
    --scapp-v2-control-border: var(--st-widget-border-color, var(--st-border-color));
    --scapp-v2-primary: var(--st-primary-color);
    --scapp-v2-font: var(--st-font);
    --scapp-v2-code-font: var(--st-code-font);
    --scapp-v2-code-bg: var(--st-code-background-color);
    --scapp-v2-base-radius: var(--st-base-radius);
    --scapp-v2-button-radius: var(--st-button-radius);
    --scapp-v2-dataframe-border: var(--st-dataframe-border-color, var(--st-border-color));
    --scapp-v2-dataframe-header-bg: var(--st-dataframe-header-background-color, var(--st-secondary-background-color));

    /* Canonical SCAPP control metrics from st_style.py. */
    --scapp-v2-control-font-size: 14px;
    --scapp-v2-control-height: 40px;

    /* Components-v2 shared control geometry. */
    --scapp-v2-control-line-height: 1.25;
    --scapp-v2-control-padding-x: 12px;
    --scapp-v2-control-option-min-height: 2.2rem;
    --scapp-v2-control-option-padding-y: .4rem;
    --scapp-v2-toggle-radius: 2px;
    --scapp-v2-checked-font-weight: 500;
    --scapp-v2-disabled-opacity: .45;

    /* Canonical content/table metrics from assets_style.py. */
    --scapp-v2-content-font-size: 1rem;
    --scapp-v2-content-line-height: 1.6;
    --scapp-v2-content-font-weight: 400;
    --scapp-v2-content-letter-spacing: normal;
    --scapp-v2-content-word-spacing: normal;
    --scapp-v2-table-cell-padding: 8px;
    --scapp-v2-panel-padding: 15px;
    --scapp-v2-panel-gap: 20px;
    --scapp-v2-code-font-size: .75rem;
    --scapp-v2-segment-id-width: 60px;
}

/* Shared single-line control contract. */
[data-ss-collection-root] [data-scapp-control="button"],
[data-ss-collection-root] [data-scapp-control="select"],
[data-ss-collection-root] [data-scapp-control="input"],
[data-ss-collection-root] [data-scapp-control="toggle"] {
    box-sizing: border-box;
    height: var(--scapp-v2-control-height);
    min-height: var(--scapp-v2-control-height);
    border: 1px solid var(--scapp-v2-control-border);
    color: var(--scapp-v2-text);
    background: var(--scapp-v2-bg);
    font-family: var(--scapp-v2-font);
    font-size: var(--scapp-v2-control-font-size);
    font-weight: 400;
    line-height: var(--scapp-v2-control-line-height);
    transition: background-color .2s ease, border-color .2s ease, color .2s ease;
}

[data-ss-collection-root] [data-scapp-control="button"],
[data-ss-collection-root] [data-scapp-control="toggle"] {
    padding: 0 var(--scapp-v2-control-padding-x);
    border-radius: var(--scapp-v2-button-radius);
    cursor: pointer;
}

[data-ss-collection-root] [data-scapp-control="select"],
[data-ss-collection-root] [data-scapp-control="input"] {
    padding: 0 var(--scapp-v2-control-padding-x);
    border-radius: var(--scapp-v2-base-radius);
}

[data-ss-collection-root] [data-scapp-control="toggle"] {
    border-radius: var(--scapp-v2-toggle-radius);
    color: var(--scapp-v2-muted-text);
}

[data-ss-collection-root] [data-scapp-control="toggle"][aria-pressed="true"] {
    background: var(--scapp-v2-bg-secondary);
    color: var(--scapp-v2-text);
    font-weight: var(--scapp-v2-checked-font-weight);
}

[data-ss-collection-root] [data-scapp-control="button"]:hover:not(:disabled),
[data-ss-collection-root] [data-scapp-control="toggle"]:hover:not(:disabled),
[data-ss-collection-root] [data-scapp-control="select"]:hover:not(:disabled),
[data-ss-collection-root] [data-scapp-control="input"]:hover:not(:disabled) {
    background: var(--scapp-v2-bg-secondary);
}

[data-ss-collection-root] [data-scapp-control="button"]:focus-visible,
[data-ss-collection-root] [data-scapp-control="select"]:focus-visible,
[data-ss-collection-root] [data-scapp-control="input"]:focus-visible,
[data-ss-collection-root] [data-scapp-control="toggle"]:focus-visible {
    outline: 2px solid var(--scapp-v2-primary);
    outline-offset: 1px;
}

[data-ss-collection-root] [data-scapp-control="button"]:disabled,
[data-ss-collection-root] [data-scapp-control="select"]:disabled,
[data-ss-collection-root] [data-scapp-control="input"]:disabled,
[data-ss-collection-root] [data-scapp-control="toggle"]:disabled {
    opacity: var(--scapp-v2-disabled-opacity);
    cursor: default;
}

[data-ss-collection-root] [data-scapp-option] {
    box-sizing: border-box;
    min-height: var(--scapp-v2-control-option-min-height);
    padding: var(--scapp-v2-control-option-padding-y) var(--scapp-v2-control-padding-x);
    border: 0;
    color: var(--scapp-v2-text);
    background: transparent;
    font-family: var(--scapp-v2-font);
    font-size: var(--scapp-v2-control-font-size);
    font-weight: 400;
    line-height: var(--scapp-v2-control-line-height);
    white-space: normal;
    overflow-wrap: anywhere;
}

[data-ss-collection-root] [data-scapp-option]:hover,
[data-ss-collection-root] [data-scapp-option]:focus-visible,
[data-ss-collection-root] [data-scapp-option][aria-selected="true"] {
    background: var(--scapp-v2-bg-secondary);
}

[data-ss-collection-root] [data-scapp-option]:focus-visible {
    outline: 2px solid var(--scapp-v2-primary);
    outline-offset: -2px;
}

[data-ss-collection-root] table[data-scapp-table] {
    border-collapse: collapse;
    color: var(--scapp-v2-text);
    background: var(--scapp-v2-bg);
    font-family: var(--scapp-v2-font);
    font-size: var(--scapp-v2-content-font-size);
    line-height: var(--scapp-v2-content-line-height);
}

[data-ss-collection-root] table[data-scapp-table] th,
[data-ss-collection-root] table[data-scapp-table] td {
    padding: var(--scapp-v2-table-cell-padding);
    border: 1px solid var(--scapp-v2-border);
    vertical-align: top;
}

[data-ss-collection-root] table[data-scapp-table] thead th {
    background: var(--scapp-v2-bg-secondary);
    font-weight: 600;
}
[data-ss-collection-root] {
  /* Accepted SCAPP hover border has no equivalent native semantic token. */
  --ss-hover-border: #b5b4ad;
  color: var(--scapp-v2-text);
  background: var(--scapp-v2-bg);
  font-family: var(--scapp-v2-font);
  font-size: var(--scapp-v2-content-font-size);
  line-height: var(--scapp-v2-content-line-height);
  font-weight: var(--scapp-v2-content-font-weight);
  letter-spacing: normal;
  word-spacing: normal;
  width: 100%;
  box-sizing: border-box;
}
[data-ss-collection-root] h2 { font-size: 1.5rem; font-weight: 600; line-height: 1.3; margin: 0 0 1rem; }
[data-ss-collection-root] .ss-controls { display: grid; grid-template-columns: 1fr 2fr; gap: 1rem; }
[data-ss-collection-root] .ss-control-label {
  display: block;
  position: relative;
  font-family: var(--scapp-v2-font);
  font-size: var(--scapp-v2-control-font-size);
  line-height: var(--scapp-v2-control-line-height);
  color: var(--scapp-v2-text);
}
[data-ss-collection-root] .ss-select { position: relative; margin-top: .35rem; }
[data-ss-collection-root] .ss-select > button {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  text-align: left;
  cursor: pointer;
  color: var(--scapp-select-text);
  background: var(--scapp-select-background);
  border-color: var(--scapp-select-border);
  padding-right: 16px;
  transition: initial;
}
[data-ss-collection-root] .ss-select > button:hover:not(:disabled),
[data-ss-collection-root] .ss-select > button:focus-visible {
  border-color: var(--scapp-select-hover-border);
  outline: none;
  box-shadow: none;
}
[data-ss-collection-root] .ss-select-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; min-width: 0; }
[data-ss-collection-root] .ss-chevron { width: 7px; height: 7px; border-right: 1px solid; border-bottom: 1px solid; transform: rotate(45deg); margin-top: -4px; flex: none; }
[data-ss-collection-root] .ss-options {
  position: absolute;
  top: calc(100% + 2px);
  left: 0;
  right: 0;
  z-index: 100;
  max-height: 300px;
  overflow: auto;
  color: var(--scapp-select-text);
  background: var(--scapp-select-menu-background);
  border: 1px solid var(--scapp-select-border);
  box-shadow: 0 4px 12px #0002;
}
[data-ss-collection-root] .ss-options button { display: block; width: 100%; text-align: left; cursor: pointer; border-radius: 0; }
[data-ss-collection-root] .ss-options button:hover,
[data-ss-collection-root] .ss-options button:focus,
[data-ss-collection-root] .ss-options button[aria-selected="true"] { background: var(--scapp-select-active-background); outline: none; }
[data-ss-collection-root] .ss-options button[aria-selected="true"] { font-weight: 600; }
[data-ss-collection-root] .ss-table-viewport:focus-visible { outline: 1px solid var(--ss-hover-border); outline-offset: 2px; }
[data-ss-collection-root] .ss-statistics { font-size: .875rem; margin: .6rem 0; }
[data-ss-collection-root] .ss-empty { padding: 1rem; background: #fff8db; border-radius: .5rem; }
[data-ss-collection-root] .ss-table-viewport { overflow-x: auto; width: 100%; }
[data-ss-collection-root] [hidden] { display: none; }
[data-ss-collection-root] table[data-scapp-table] {
  background: transparent;
  width: 100%;
  margin: 0;
}
[data-ss-collection-root] caption { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
[data-ss-collection-root] th, [data-ss-collection-root] td {
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  text-align: left;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
[data-ss-collection-root] table[data-scapp-table] thead th { background: transparent; white-space: nowrap; }
[data-ss-collection-root] .ss-row-index { font-weight: 400; color: var(--scapp-v2-muted-text); }
[data-ss-collection-root] .ss-uid { color: var(--st-violet-color, #8b5cf6); }
[data-ss-collection-root] a { color: var(--st-link-color, #0068c9); text-decoration: underline; }
[data-ss-collection-root] a.ss-uid { color: var(--st-violet-color, #8b5cf6); }
@media (max-width: 600px) { [data-ss-collection-root] .ss-controls { grid-template-columns: 1fr; gap: .6rem; } }

[data-ss-collection-root] {
    --scapp-select-background: var(--st-secondary-background-color, #ecebe3);
    --scapp-select-menu-background: var(--st-background-color, #fdfdf8);
    --scapp-select-text: var(--st-text-color, #3d3a2a);
    --scapp-select-border: var(--st-widget-border-color, var(--st-border-color, #d3d2ca));
    --scapp-select-hover-border: #b8b6ad;
    --scapp-select-active-background: var(--st-secondary-background-color, #ecebe3);
}
